const MediaTile_data = [
    { arialabelledby: "block_c295a1f794ea49d71f5f4167dd6e8c51-tab-0", id: "block_c295a1f794ea49d71f5f4167dd6e8c51-panel-0", text: "Our Earned Media approach breaks down channel and department silos to create one connected strategy for how brands are discovered and chosen. We unite AEO/GEO, SEO, App Store Optimization, Content Marketing, Digital PR, Influencer Marketing, Organic Social Media, and Email Marketing to build authority, expand visibility, earn attention, and drive sustainable growth everywhere audiences search and discover. Our award-winning work spans both global Enterprise brands and ambitious SMBs, combining proven expertise with strategies tailored to each brand’s scale, audience, and growth goals.", kind: "image", alt: "neil-pointing-up-tall-1", sizes: "(max-width: 575px) 100vw, 575px", imgSrc: "/assets/cloned/images/f10e0f4d8406.png", srcSet: "/assets/cloned/images/f10e0f4d8406.png 575w, /assets/cloned/images/1521150cfced.png 350w" },
    { arialabelledby: "block_c295a1f794ea49d71f5f4167dd6e8c51-tab-1", id: "block_c295a1f794ea49d71f5f4167dd6e8c51-panel-1", text: "Our Paid Media approach treats every channel as one connected investment rather than isolated budgets. We combine Media Strategy & Planning, Paid Search, Paid Social, Programmatic & Display, Marketplaces, and Streaming to reach audiences in the moments that matter. Our approach to media unification — recognized by Google — connects audiences, channels, data, and investment to maximize performance across the media ecosystem. We focus on the metrics that move revenue, uncover growth opportunities, and make every media dollar work harder — not vanity impressions.", alt: "neil-smiling-tall", sizes: "(max-width: 575px) 100vw, 575px", imgSrc: "/assets/cloned/images/2e4a7527c5ca.png", srcSet: "/assets/cloned/images/2e4a7527c5ca.png 575w, /assets/cloned/images/b70f2c76adba.png 350w" },
    { arialabelledby: "block_c295a1f794ea49d71f5f4167dd6e8c51-tab-2", id: "block_c295a1f794ea49d71f5f4167dd6e8c51-panel-2", text: "Our Data & Analytics approach turns scattered marketing data into clear, actionable decisions your team can use to drive growth. We bring together Insights, Dashboard Development, Conversion Rate Optimization, User Experience, Front End Development, and Ad Operations to create a connected view of performance across the customer journey. By uncovering what actually drives results, exposing gaps and opportunities in your funnel, and making every channel accountable to the same numbers, we help teams move faster, optimize smarter, and turn data into business impact.", alt: "neil-thumbs-up-tall", sizes: "auto, (max-width: 575px) 100vw, 575px", imgSrc: "/assets/cloned/images/51ae77eb4243.png", srcSet: "/assets/cloned/images/51ae77eb4243.png 575w, /assets/cloned/images/2d25dc0e05a5.png 350w" },
    { arialabelledby: "block_c295a1f794ea49d71f5f4167dd6e8c51-tab-3", id: "block_c295a1f794ea49d71f5f4167dd6e8c51-panel-3", text: "Our Creative approach turns bold ideas into work that stops the scroll, earns attention, and drives action. We unite Performance Creative, Branding, Content Production, Website Design, Graphic & Motion Design, and Audio Production to build brands people don’t just recognize — they remember. From thumb-stopping ads to immersive digital experiences, every concept is grounded in strategy, shaped by culture, and engineered to perform in the channel it was made for. Because great creative shouldn’t just look good. It should work hard, move fast, and make an impact.", alt: "neil-serious-tall", sizes: "auto, (max-width: 575px) 100vw, 575px", imgSrc: "/assets/cloned/images/1ca8959e16cb.png", srcSet: "/assets/cloned/images/1ca8959e16cb.png 575w, /assets/cloned/images/8f56b02c7b77.png 350w" }
];
